from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class HostnameEqId(SchemaObject):
    hostname = SchemaField(name='hostname')
    eq_id = SchemaField(name='eqId')

    def __init__(self, hostname, eq_id):
        self.hostname = hostname
        self.eq_id = eq_id

        super(HostnameEqId, self).__init__()


class TraceCommonConfigurationV1(SchemaObject):
    uplane_ip_address = SchemaField(name="uplaneIpAddress", optional=True)
    uplane_port = SchemaField(name="uplanePort", optional=True)
    dscp = SchemaField(name="dscp", optional=True)
    eq_id = SchemaField(name="eqId", klass=HostnameEqId, many=True, optional=True)

    def __init__(self, uplane_ip_address, uplane_port, dscp, eq_id):
        self.uplane_ip_address = uplane_ip_address
        self.uplane_port = uplane_port
        self.dscp = dscp
        self.eq_id = eq_id
        super(TraceCommonConfigurationV1, self).__init__()
